using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    async Task ApplyMigrationsAsync(AppDbContext db)
    {
        // EF Core 9 manages its own transactions during Migrate; wrapping in a
        // user transaction now throws. Simply call MigrateAsync directly.
        await db.Database.MigrateAsync();
    }
}

