using Microsoft.EntityFrameworkCore;

// Cosmos DB provider fixes for EF Core 9 migration.
// These configurations preserve compatibility with existing documents.
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: discriminator property renamed from "Discriminator" to "$type".
        // Existing documents use the old name — explicitly preserve it.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change: id property no longer includes discriminator prefix.
        // Existing docs have "Session|<key>" format — preserve it for backward compat.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }

    // Breaking change: Sync I/O no longer supported by the Cosmos provider.
    // All queries/saves MUST use async equivalents (ToListAsync, SaveChangesAsync, etc.).
    public async Task<List<Session>> GetActiveSessionsAsync()
    {
        // WRONG (throws in EF Core 9):  return Sessions.Where(...).ToList();
        return await Sessions.Where(s => s.IsActive).ToListAsync();
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public bool IsActive { get; set; }
}

